const cfg = $('Config').first().json;
function idOf(v){ const s=String(v||''); const m=s.match(/\/d\/([a-zA-Z0-9-_]+)/); return m ? m[1] : s.trim(); }
return [{ json: { sourceId: idOf(cfg.sourceId), destId: idOf(cfg.destId), sourceRaw: cfg.sourceId, destRaw: cfg.destId } }];

const cfg = $('Config').first().json;
const meta = $input.first().json;
const excluded = String(cfg.excludedTabs || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const props = (meta.sheets || []).map(s => (s && s.properties && s.properties.title) ? s.properties.title : null).filter(Boolean);
const startupTabs = props.filter(t => excluded.indexOf(String(t).trim().toLowerCase()) === -1);
const sid = $('Extract IDs').first().json.sourceId;
const base = 'https://sheets.googleapis.com/v4/spreadsheets/' + encodeURIComponent(sid) + '/values:batchGet';
const qp = ['majorDimension=ROWS', 'valueRenderOption=UNFORMATTED_VALUE', 'dateTimeRenderOption=FORMATTED_STRING'];
const rq = startupTabs.map(t => 'ranges=' + encodeURIComponent("'" + String(t).replace(/'/g, "''") + "'"));
const url = base + '?' + qp.concat(rq).join('&');
return [{ json: { url: url, startupTabs: startupTabs } }];

const resp = $input.first().json;
const vr = resp.valueRanges || [];
const alias = {
  'dealid':'deal_id',
  'investorvcname':'investor_name','investorname':'investor_name','investor':'investor_name','vcname':'investor_name','investors':'investor_name',
  'owner':'owner','priority':'priority',
  'dealshared':'deal_shared',
  'dateshared':'date_shared','channel':'channel','dayssinceshared':'days_since_shared',
  'followup1done':'followup1_done','fu1done':'followup1_done','followup1':'followup1_done',
  'followup1date':'followup1_date','fu1date':'followup1_date',
  'followup2done':'followup2_done','fu2done':'followup2_done','followup2':'followup2_done',
  'followup2date':'followup2_date','fu2date':'followup2_date',
  'followup3done':'followup3_done','fu3done':'followup3_done','followup3':'followup3_done',
  'followup3date':'followup3_date','fu3date':'followup3_date',
  'totalfollowups':'total_followups',
  'lastcontactdate':'last_contact_date','dayssincelastcontact':'days_since_last_contact',
  'meetingscheduled':'meeting_scheduled',
  'dateofmeetingscheduled':'meeting_date','meetingdate':'meeting_date',
  'noofmeetingsheld':'meetings_held','meetingsheld':'meetings_held','numberofmeetingsheld':'meetings_held',
  'lastmeetingdate':'last_meeting_date','lastmeetingoutcome':'last_meeting_outcome',
  'investorresponse':'investor_response','response':'investor_response',
  'passreason':'pass_reason','currentstage':'current_stage','stage':'current_stage',
  'nextaction':'next_action','nextactiondue':'next_action_due','daystooverdue':'days_to_overdue',
  'committedamountinrcr':'committed_amount','committedamount':'committed_amount',
  'dealstatus':'deal_status','status':'deal_status','notes':'notes'
};
function nh(h){ return String(h).toLowerCase().replace(/[^a-z0-9]+/g,''); }
const out = [];
for (const block of vr) {
  const range = block.range || '';
  let tab = range; const bang = range.lastIndexOf('!'); if (bang >= 0) tab = range.slice(0, bang);
  tab = tab.replace(/^'/, '').replace(/'$/, '').replace(/''/g, "'").trim();
  const rows = block.values || [];
  if (!rows.length) continue;
  let headerIdx = -1;
  for (let h = 0; h < rows.length; h++) { const cells = (rows[h] || []).map(x => nh(x)); if (cells.indexOf('investorvcname') !== -1 || (cells.indexOf('dealid') !== -1 && cells.indexOf('dealshared') !== -1)) { headerIdx = h; break; } }
  if (headerIdx === -1) continue;
  const canon = (rows[headerIdx] || []).map(h => alias[nh(h)] || null);
  for (let r = headerIdx + 1; r < rows.length; r++) {
    const row = rows[r] || [];
    const rec = { startup_name: tab, _source_row: r + 1 };
    for (let c = 0; c < canon.length; c++) { if (canon[c]) { const v = row[c]; rec[canon[c]] = (v === undefined ? null : v); } }
    const inv = rec.investor_name != null && String(rec.investor_name).trim() !== '';
    if (!inv) continue;
    const invLow = String(rec.investor_name).trim().toLowerCase();
    if (['investor / vc name','investor','vc name','total','totals','grand total','instructions','template'].indexOf(invLow) !== -1) continue;
    const meaningful = [rec.deal_shared, rec.investor_response, rec.current_stage, rec.deal_status, rec.followup1_done, rec.followup2_done, rec.followup3_done, rec.meeting_scheduled, rec.date_shared].some(x => x != null && String(x).trim() !== '');
    if (!meaningful) continue;
    out.push({ json: rec });
  }
}
return out;

const cfg = $('Config').first().json;
let src = $('Normalize Source Rows').all().map(i => i.json);
const dest = $('Read Destination').all().map(i => i.json);
const testLimit = Number(cfg.testLimit) || 0;
const months = { jan:0,feb:1,mar:2,apr:3,may:4,jun:5,jul:6,aug:7,sep:8,oct:9,nov:10,dec:11 };
function pd(v){ if(v===null||v===undefined) return null; const s=String(v).trim(); if(!s) return null; const mName=s.match(/^(\d{1,2})[\s\-\/]+([A-Za-z]{3,})[\s,\-\/]+(\d{2,4})?$/); if(mName){ const day=+mName[1]; const mon=months[mName[2].slice(0,3).toLowerCase()]; let yr=mName[3]?+mName[3]:new Date().getFullYear(); if(yr<100) yr+=2000; if(mon!=null) return {ts:new Date(yr,mon,day).getTime(),raw:s}; } const mNum=s.match(/^(\d{1,2})[\-\/](\d{1,2})[\-\/](\d{2,4})$/); if(mNum){ const day=+mNum[1]; const mon=+mNum[2]-1; let yr=+mNum[3]; if(yr<100) yr+=2000; if(mon>=0&&mon<12) return {ts:new Date(yr,mon,day).getTime(),raw:s}; } const t=Date.parse(s); if(!isNaN(t)) return {ts:t,raw:s}; return {ts:null,raw:s}; }
function fmt(ts){ const dt=new Date(ts); const y=dt.getFullYear(); const m=('0'+(dt.getMonth()+1)).slice(-2); const da=('0'+dt.getDate()).slice(-2); return y+'-'+m+'-'+da; }
function ymdOf(v){ const p=pd(v); if(!p||p.ts==null) return null; return fmt(p.ts); }
let runYmd=''; if(cfg.runDate!=null && String(cfg.runDate).trim()!==''){ runYmd=ymdOf(cfg.runDate)||''; }
if(!runYmd){ const nowI=new Date(Date.now()+5.5*3600*1000); runYmd=nowI.getUTCFullYear()+'-'+('0'+(nowI.getUTCMonth()+1)).slice(-2)+'-'+('0'+nowI.getUTCDate()).slice(-2); }
// Process ALL deals in the source sheet regardless of date_shared.
// Deals already present in the destination are skipped by the dedupe logic below.
function yes(v){ if(v===null||v===undefined) return false; const s=String(v).trim().toLowerCase(); return ['yes','y','done','true','1','completed','complete'].indexOf(s)!==-1; }
function norm(v){ return String(v==null?'':v).toLowerCase().trim().replace(/[^a-z0-9 ()]+/g,' ').replace(/\s+/g,' ').trim(); }
function nonEmpty(v){ return v!=null && String(v).trim()!==''; }
function splitList(v){ if(!nonEmpty(v)) return []; return String(v).split(',').map(s=>s.trim()).filter(Boolean); }
function splitParts(v){ if(!nonEmpty(v)) return []; return String(v).split(/\n|;/).map(s=>s.trim()).filter(Boolean); }
function dedupePreserve(arr){ const seen={}; const out=[]; for(const a of arr){ const k=a.toLowerCase(); if(!seen[k]){ seen[k]=1; out.push(a);} } return out; }
function dedupeNames(arr){ const seen={}; const out=[]; for(const a of arr){ if(a==null) continue; const s=String(a).trim(); if(s==='') continue; const k=s.toLowerCase().replace(/[^a-z0-9]+/g,''); if(!k) continue; if(!seen[k]){ seen[k]=1; out.push(s);} } return out; }
function isInterested(r){ const blob=norm(r.investor_response)+' '+norm(r.current_stage)+' '+norm(r.deal_status); if(yes(r.meeting_scheduled)||(Number(r.meetings_held)||0)>0) return true; return ['interested','picked','meeting','asked for documents','asked for docs','reviewing','review','due diligence','term sheet','committed','won'].some(p=>blob.indexOf(p)!==-1); }
function isPassed(r){ const blob=norm(r.investor_response)+' '+norm(r.deal_status)+' '+norm(r.current_stage); return ['passed','pass','lost','declined','not relevant','not interested'].some(p=>blob.indexOf(p)!==-1); }
function activityDate(r){ const ds=[r.date_shared,r.followup1_date,r.followup2_date,r.followup3_date,r.last_contact_date,r.last_meeting_date,r.meeting_date]; let best=null; for(const d of ds){ const p=pd(d); if(p&&p.ts!=null){ if(best===null||p.ts>best) best=p.ts; } } return best; }
function fuRound(r){ if(!r) return 0; if(yes(r.followup3_done)) return 3; if(yes(r.followup2_done)) return 2; if(yes(r.followup1_done)) return 1; return 0; }
function lastFU(r){ let best=null; const xs=[r?r.followup1_date:null,r?r.followup2_date:null,r?r.followup3_date:null]; for(const x of xs){ const p=pd(x); if(p&&p.ts!=null){ if(best===null||p.ts>best) best=p.ts; } } return best; }
function stopChase(r){ const blob=norm(r.investor_response)+' '+norm(r.current_stage)+' '+norm(r.deal_status)+' '+norm(r.next_action); if(yes(r.meeting_scheduled)) return true; return ['meeting scheduled','asked for documents','asked for docs','interested','picked','committed','won','close','closed','lost','not relevant','term sheet','due diligence'].some(s=>blob.indexOf(s)!==-1); }
function statusOf(r){ if(!r) return ''; if(yes(r.meeting_scheduled)||(Number(r.meetings_held)||0)>0) return 'Meeting Scheduled'; if(isInterested(r)) return 'Interested'; const fr=fuRound(r); if(fr===3) return 'Follow-up Done 3'; if(fr===2) return 'Follow-up Done 2'; if(fr===1) return 'Follow-up Done'; if(yes(r.deal_shared)||nonEmpty(r.date_shared)) return 'Deal Shared'; return 'Other'; }
function prank(p){ const s=norm(p); if(s.indexOf('high')!==-1||s==='1'||s==='p1') return 3; if(s.indexOf('med')!==-1||s==='2'||s==='p2') return 2; if(s.indexOf('low')!==-1||s==='3'||s==='p3') return 1; return 0; }
const destMap={};
dest.forEach((d,idx)=>{ const name=d['Investor / VC Name']; if(!nonEmpty(name)) return; const key=norm(name); if(!(key in destMap)) destMap[key]={json:d, rowNumber:(d.row_number!=null?d.row_number:idx+2)}; });
const groups={}; const unmatchedMap={};
for(const rec of src){ const key=norm(rec.investor_name); if(destMap[key]){ if(!groups[key]) groups[key]={dest:destMap[key], rows:[]}; groups[key].rows.push(rec);} else { if(!unmatchedMap[key]) unmatchedMap[key]={name:rec.investor_name, startups:{}, rows:[]}; unmatchedMap[key].startups[rec.startup_name]=1; unmatchedMap[key].rows.push(rec._source_row+'@'+rec.startup_name); } }
const results=[];
Object.keys(groups).forEach(key=>{
  const g=groups[key]; const dOrig=g.dest.json; const d={}; for(const dk in dOrig){ d[String(dk).trim()]=dOrig[dk]; } const rows=g.rows; const destName=d['Investor / VC Name'];
  const sourceStartups=dedupeNames(rows.map(r=>r.startup_name));
  const sharedRows=rows.filter(r=>yes(r.deal_shared)||nonEmpty(r.date_shared));
  const sharedStartups=dedupeNames(sharedRows.map(r=>r.startup_name));
  const existingAll=splitList(d['All Deals Shared till date']);
  const proposedAll=dedupeNames(existingAll.concat(sharedStartups));
  const destLastDate=pd(d['Last Deal Mail Sent Date/call done']);
  const destFollowDate=pd(d['Last Follow-up Sent Date']);
  let latestRefTs=null;
  if(destLastDate&&destLastDate.ts!=null) latestRefTs=destLastDate.ts;
  if(destFollowDate&&destFollowDate.ts!=null && (latestRefTs===null||destFollowDate.ts>latestRefTs)) latestRefTs=destFollowDate.ts;
  let maxShareTs=null; sharedRows.forEach(r=>{ const p=pd(r.date_shared); if(p&&p.ts!=null){ if(maxShareTs===null||p.ts>maxShareTs) maxShareTs=p.ts; } });
  let latestStartups=[]; if(maxShareTs!==null) latestStartups=dedupeNames(sharedRows.filter(r=>{ const p=pd(r.date_shared); return p&&p.ts===maxShareTs; }).map(r=>r.startup_name));
  let proposedLatest=d['Latest deal shared'];
  if(latestStartups.length){ if(!(latestRefTs!==null&&maxShareTs<latestRefTs)) proposedLatest=latestStartups.join(', '); }
  if(!nonEmpty(proposedLatest) && sharedStartups.length) proposedLatest=sharedStartups.join(', ');
  if(!nonEmpty(proposedLatest) && sourceStartups.length) proposedLatest=sourceStartups.join(', ');
  if(!nonEmpty(proposedLatest)) proposedLatest=d['Latest deal shared'];
  let srcActMax=null; rows.forEach(r=>{ const a=activityDate(r); if(a!=null){ if(srcActMax===null||a>srcActMax) srcActMax=a; } });
  let proposedMail=d['Last Deal Mail Sent Date/call done'];
  if(srcActMax!==null){ if(!(destLastDate&&destLastDate.ts!=null&&srcActMax<destLastDate.ts)) proposedMail=fmt(srcActMax); }
  if(!nonEmpty(proposedMail)) proposedMail=d['Last Deal Mail Sent Date/call done'];
  const pickedSrc=dedupeNames(rows.filter(isInterested).map(r=>r.startup_name));
  const existingPicked=splitList(d['Picked / Interested Deals']);
  const proposedPicked=dedupeNames(existingPicked.concat(pickedSrc));
  const activeRows=rows.filter(r=>(yes(r.deal_shared)||nonEmpty(r.date_shared)) && !isPassed(r));
  let latestActive=null; let latestActiveTs=null; activeRows.forEach(r=>{ const a=activityDate(r); if(latestActive===null || (a!=null && (latestActiveTs===null||a>latestActiveTs))){ latestActive=r; latestActiveTs=a; } });
  let proposedFURound = latestActive!==null ? fuRound(latestActive) : (nonEmpty(d['Follow-up Round'])?d['Follow-up Round']:0);
  const efu=pd(d['Last Follow-up Sent Date']); let proposedFUDate=d['Last Follow-up Sent Date']; const lfu=latestActive?lastFU(latestActive):null; if(lfu!=null){ if(!(efu&&efu.ts!=null&&lfu<efu.ts)) proposedFUDate=fmt(lfu); } if(!nonEmpty(proposedFUDate)) proposedFUDate=d['Last Follow-up Sent Date'];
  let followupNeeded=false; activeRows.forEach(r=>{ if(!stopChase(r)) followupNeeded=true; });
  const proposedFUNeeded = activeRows.length ? (followupNeeded?'Yes':'No') : (nonEmpty(d['Follow-up Needed?'])?d['Follow-up Needed?']:'No');
  let proposedStatus = latestActive ? statusOf(latestActive) : '';
  if(!nonEmpty(proposedStatus)){ if(activeRows.length===0 && rows.some(isPassed)) proposedStatus='Passed'; else proposedStatus=d['Current Status']; }
  const existingPassParts=splitParts(d['Pass Reason']); const passItems=[]; rows.filter(isPassed).forEach(r=>{ if(nonEmpty(r.pass_reason)) passItems.push(r.startup_name+': '+String(r.pass_reason).trim()); });
  let proposedPass=d['Pass Reason']; if(passItems.length){ proposedPass=dedupePreserve(existingPassParts.concat(passItems)).join('; '); } if(!nonEmpty(proposedPass)) proposedPass=d['Pass Reason'];
  const existingFbParts=splitParts(d['Investor Feedback / Response']); const fbItems=[]; rows.forEach(r=>{ let f=null; if(nonEmpty(r.investor_response) && ['no response','?','na','n a'].indexOf(norm(r.investor_response))===-1) f=r.investor_response; else if(nonEmpty(r.last_meeting_outcome)) f=r.last_meeting_outcome; else if(nonEmpty(r.notes)) f=r.notes; if(nonEmpty(f)) fbItems.push(r.startup_name+': '+String(f).trim()); });
  let proposedFeedback=d['Investor Feedback / Response']; if(fbItems.length){ proposedFeedback=dedupePreserve(existingFbParts.concat(fbItems)).join('; '); } if(!nonEmpty(proposedFeedback)) proposedFeedback=d['Investor Feedback / Response'];
  let chosenAction=null; if(activeRows.length){ let best=null; let bestDue=null; activeRows.forEach(r=>{ if(!nonEmpty(r.next_action)) return; const p=pd(r.next_action_due); const due=p&&p.ts!=null?p.ts:null; if(best===null){ best=r; bestDue=due; } else if(due!=null && (bestDue===null||due<bestDue)){ best=r; bestDue=due; } }); if(!best) best=latestActive; chosenAction=best?best.next_action:null; }
  let proposedNext = nonEmpty(chosenAction)?String(chosenAction).trim():d['Next Action']; if(!nonEmpty(proposedNext)) proposedNext=d['Next Action'];
  let bestPr=null; let bestRank=-1; (activeRows.length?activeRows:rows).forEach(r=>{ if(nonEmpty(r.priority)){ const rk=prank(r.priority); if(rk>bestRank){ bestRank=rk; bestPr=r.priority; } } });
  let proposedPriority = nonEmpty(bestPr)?String(bestPr).trim():d['Priority']; if(!nonEmpty(proposedPriority)) proposedPriority=d['Priority'];
  const existingRParts=splitParts(d['Remarks / Old Status']); const newNotes=[]; rows.forEach(r=>{ if(nonEmpty(r.notes)){ const n=r.startup_name+': '+String(r.notes).trim(); if(existingRParts.indexOf(n)===-1) newNotes.push(n); } });
  const proposedRemarks = newNotes.length ? dedupePreserve(existingRParts.concat(newNotes)).join('; ') : d['Remarks / Old Status'];
  const proposed={ 'Latest deal shared':proposedLatest, 'All Deals Shared till date':proposedAll.join(', '), 'Picked / Interested Deals':proposedPicked.join(', '), 'Last Deal Mail Sent Date/call done':proposedMail, 'Current Status':proposedStatus, 'Follow-up Round':proposedFURound, 'Last Follow-up Sent Date':proposedFUDate, 'Follow-up Needed?':proposedFUNeeded, 'Pass Reason':proposedPass, 'Investor Feedback / Response':proposedFeedback, 'Next Action':proposedNext, 'Priority':proposedPriority, 'Remarks / Old Status':proposedRemarks };
  const keys=Object.keys(proposed); const existing={}; keys.forEach(k=>{ existing[k]=d[k]; });
  const changed=[]; keys.forEach(k=>{ const a=proposed[k]==null?'':String(proposed[k]).trim(); const b=existing[k]==null?'':String(existing[k]).trim(); if(a!==b && a!=='') changed.push(k); });
  const updatePayload={ 'Investor / VC Name':destName }; keys.forEach(k=>{ const a=proposed[k]==null?'':String(proposed[k]); updatePayload[k]= nonEmpty(a)?proposed[k]:(existing[k]==null?'':existing[k]); });
  results.push({ _type:'matched', investor:destName, destRowNumber:g.dest.rowNumber, sourceStartups:sourceStartups.join(', '), existing:existing, proposed:proposed, fieldsThatWouldChange:changed, updatePayload:updatePayload });
});
let matched=results; if(testLimit>0) matched=results.slice(0, testLimit);
const unmatched=Object.keys(unmatchedMap).map(k=>{ const u=unmatchedMap[k]; return { _type:'unmatched', sourceInvestorName:u.name, startups:Object.keys(u.startups).join(', '), sourceRows:u.rows.join(', '), reason:'No confident match in destination Deal Tracker' }; });
const outAll=[]; matched.forEach(m=>outAll.push({json:m})); unmatched.forEach(u=>outAll.push({json:u})); return outAll;

const cons=$('Consolidate Investor Updates').all().map(i=>i.json);
const cfg=$('Config').first().json;
function pd2(v){ if(v==null) return null; const s=String(v).trim(); if(!s) return null; const months={jan:0,feb:1,mar:2,apr:3,may:4,jun:5,jul:6,aug:7,sep:8,oct:9,nov:10,dec:11}; const mN=s.match(/^(\d{1,2})[\s\-\/]+([A-Za-z]{3,})[\s,\-\/]+(\d{2,4})?$/); if(mN){ const day=+mN[1]; const mon=months[mN[2].slice(0,3).toLowerCase()]; let yr=mN[3]?+mN[3]:new Date().getFullYear(); if(yr<100) yr+=2000; if(mon!=null) return new Date(yr,mon,day); } const mNum=s.match(/^(\d{1,2})[\-\/](\d{1,2})[\-\/](\d{2,4})$/); if(mNum){ const day=+mNum[1]; const mon=+mNum[2]-1; let yr=+mNum[3]; if(yr<100) yr+=2000; if(mon>=0&&mon<12) return new Date(yr,mon,day); } const t=Date.parse(s); if(!isNaN(t)) return new Date(t); return null; }
function ymd(dt){ return dt.getFullYear()+'-'+('0'+(dt.getMonth()+1)).slice(-2)+'-'+('0'+dt.getDate()).slice(-2); }
let runYmd=''; if(cfg.runDate!=null && String(cfg.runDate).trim()!==''){ const d=pd2(cfg.runDate); if(d) runYmd=ymd(d); }
if(!runYmd){ const nowI=new Date(Date.now()+5.5*3600*1000); runYmd=nowI.getUTCFullYear()+'-'+('0'+(nowI.getUTCMonth()+1)).slice(-2)+'-'+('0'+nowI.getUTCDate()).slice(-2); }
